// Split TARGET_NICHES into one item per niche so the next HTTP node runs once per niche
const vars = $('Set Variables').first().json;
const niches = vars.TARGET_NICHES
  .split(',')
  .map(n => n.trim())
  .filter(Boolean);

return niches.map(niche => ({
  json: {
    niche,
    YOUTUBE_API_KEY: vars.YOUTUBE_API_KEY,
    CLAUDE_API_KEY: vars.CLAUDE_API_KEY,
    MY_CHANNEL_ID: vars.MY_CHANNEL_ID,
    GOOGLE_SHEET_ID: vars.GOOGLE_SHEET_ID,
    OUTLIER_THRESHOLD: vars.OUTLIER_THRESHOLD,
    TRANSCRIPT_SCRIPT_PATH: vars.TRANSCRIPT_SCRIPT_PATH
  }
}));

// Merge all niche search results, deduplicate by channelId, exclude my own channel
const vars = $('Set Variables').first().json;
const myChannelId = vars.MY_CHANNEL_ID;
const channelMap = new Map();

for (const item of $input.all()) {
  const channels = item.json.items || [];
  for (const ch of channels) {
    const channelId = ch.id && ch.id.channelId;
    if (channelId && channelId !== myChannelId && !channelMap.has(channelId)) {
      channelMap.set(channelId, {
        channelId,
        channelTitle: ch.snippet && ch.snippet.title || 'Unknown',
        channelThumbnail: ch.snippet && ch.snippet.thumbnails && ch.snippet.thumbnails.default && ch.snippet.thumbnails.default.url || '',
        YOUTUBE_API_KEY: vars.YOUTUBE_API_KEY,
        CLAUDE_API_KEY: vars.CLAUDE_API_KEY,
        GOOGLE_SHEET_ID: vars.GOOGLE_SHEET_ID,
        OUTLIER_THRESHOLD: vars.OUTLIER_THRESHOLD,
        TRANSCRIPT_SCRIPT_PATH: vars.TRANSCRIPT_SCRIPT_PATH
      });
    }
  }
}

return Array.from(channelMap.values()).map(ch => ({ json: ch }));

// Extract video IDs from channel search results for the stats batch request
const vars = $('Set Variables').first().json;
const searchResult = $input.item.json;
const channelVideos = searchResult.items || [];

const videoIds = channelVideos
  .map(v => v.id && v.id.videoId)
  .filter(Boolean);

if (videoIds.length === 0) {
  return []; // skip channels with no public videos
}

// YouTube stats API accepts up to 50 IDs per request
const chunks = [];
for (let i = 0; i < videoIds.length; i += 50) {
  chunks.push(videoIds.slice(i, i + 50).join(','));
}

return chunks.map(idChunk => ({
  json: {
    videoIds: idChunk,
    YOUTUBE_API_KEY: vars.YOUTUBE_API_KEY,
    CLAUDE_API_KEY: vars.CLAUDE_API_KEY,
    GOOGLE_SHEET_ID: vars.GOOGLE_SHEET_ID,
    OUTLIER_THRESHOLD: vars.OUTLIER_THRESHOLD,
    TRANSCRIPT_SCRIPT_PATH: vars.TRANSCRIPT_SCRIPT_PATH
  }
}));

// Score each video: outlierScore = (views / channelAvg) * recencyBoost * contentBoost
const apiResponse = $input.item.json;
const videos = apiResponse.items || [];
const vars = $('Set Variables').first().json;

if (videos.length === 0) return [];

// Channel average views
const viewCounts = videos.map(v => parseInt((v.statistics && v.statistics.viewCount) || '0', 10));
const totalViews = viewCounts.reduce((a, b) => a + b, 0);
const avgViews = totalViews / videos.length;

if (avgViews === 0) return [];

const MONEY_KEYWORDS   = ['money','earn','income','rich','profit','revenue','salary','pay','cash','wealth','financial','invest','stock','crypto','dollar','fund'];
const TIME_KEYWORDS    = ['fast','quick','minutes','days','hours','week','instantly','today','overnight','rapid','immediately'];
const CURIOSITY_KEYWORDS = ['secret','never','nobody','surprising','shocking','truth','exposed','untold','hidden','mistake','actually','really'];

const now = Date.now();
const DAY_MS = 86400000;

const results = [];

for (const video of videos) {
  const views       = parseInt((video.statistics && video.statistics.viewCount) || '0', 10);
  const publishedAt = (video.snippet && video.snippet.publishedAt) || new Date().toISOString();
  const daysSince   = (now - new Date(publishedAt).getTime()) / DAY_MS;

  // Recency boost
  let recencyBoost = 1.0;
  if      (daysSince <= 30) recencyBoost = 1.3;
  else if (daysSince <= 60) recencyBoost = 1.2;
  else if (daysSince <= 90) recencyBoost = 1.1;

  // Content boost from title keywords
  const titleLower = ((video.snippet && video.snippet.title) || '').toLowerCase();
  let contentBoost = 1.0;
  if (MONEY_KEYWORDS.some(k   => titleLower.includes(k))) contentBoost += 0.30;
  if (TIME_KEYWORDS.some(k    => titleLower.includes(k))) contentBoost += 0.20;
  if (CURIOSITY_KEYWORDS.some(k => titleLower.includes(k))) contentBoost += 0.15;

  const baseScore    = views / avgViews;
  const outlierScore = baseScore * recencyBoost * contentBoost;

  const thumbnail = video.snippet && video.snippet.thumbnails
    ? (video.snippet.thumbnails.maxres && video.snippet.thumbnails.maxres.url)
      || (video.snippet.thumbnails.high && video.snippet.thumbnails.high.url)
      || (video.snippet.thumbnails.default && video.snippet.thumbnails.default.url)
      || ''
    : '';

  results.push({
    json: {
      videoId:           video.id,
      videoTitle:        (video.snippet && video.snippet.title)       || '',
      videoUrl:          `https://www.youtube.com/watch?v=${video.id}`,
      thumbnailUrl:      thumbnail,
      channelId:         (video.snippet && video.snippet.channelId)   || '',
      channelTitle:      (video.snippet && video.snippet.channelTitle) || '',
      publishedAt,
      viewCount:         views,
      likeCount:         parseInt((video.statistics && video.statistics.likeCount)    || '0', 10),
      commentCount:      parseInt((video.statistics && video.statistics.commentCount) || '0', 10),
      channelAvgViews:   Math.round(avgViews),
      outlierScore:      Math.round(outlierScore * 100) / 100,
      baseScore:         Math.round(baseScore * 100) / 100,
      recencyBoost,
      contentBoost:      Math.round(contentBoost * 100) / 100,
      daysSincePublished: Math.round(daysSince),
      CLAUDE_API_KEY:    vars.CLAUDE_API_KEY,
      GOOGLE_SHEET_ID:   vars.GOOGLE_SHEET_ID,
      OUTLIER_THRESHOLD: vars.OUTLIER_THRESHOLD,
      TRANSCRIPT_SCRIPT_PATH: vars.TRANSCRIPT_SCRIPT_PATH
    }
  });
}

return results;

// Parse transcript stdout and build Claude API request body
const cmdOutput  = $input.item.json;
const videoData  = $('Loop Over Outliers').item.json;
const claudeKey  = videoData.CLAUDE_API_KEY;

let transcriptText = 'No transcript available for this video.';
try {
  const parsed = JSON.parse(cmdOutput.stdout || '{}');
  if (parsed.success && parsed.transcript) {
    transcriptText = parsed.transcript;
  } else {
    transcriptText = 'Transcript unavailable: ' + (parsed.error || 'unknown error');
  }
} catch (e) {
  transcriptText = 'Error reading transcript output.';
}

// Keep within Claude context limits
if (transcriptText.length > 15000) {
  transcriptText = transcriptText.substring(0, 15000) + ' [truncated]';
}

const prompt = `You are a YouTube content strategist helping a creator identify winning video topics.

Here is a high-performing outlier video from a competitor channel:

Title: "${videoData.videoTitle}"
Channel: ${videoData.channelTitle}
Views: ${videoData.viewCount.toLocaleString()} (${videoData.outlierScore}x the channel average)
Published: ${videoData.publishedAt.split('T')[0]}

Transcript:
${transcriptText}

Provide your analysis in EXACTLY this format — no extra text:

SUMMARY: [2–3 sentences describing the main topic and the single most valuable insight from this video]

ALT TITLES:
1. [Compelling title adapted for a new/growing channel, same core hook]
2. [Alternative angle on the same topic]
3. [Curiosity-gap or number-based variant]`;

const requestBody = {
  model: 'claude-opus-4-7',
  max_tokens: 512,
  messages: [
    { role: 'user', content: prompt }
  ]
};

return [{
  json: {
    ...videoData,
    transcriptText,
    transcriptAvailable: !transcriptText.startsWith('Transcript unavailable') && !transcriptText.startsWith('No transcript'),
    claudeKey,
    claudeRequestBody: JSON.stringify(requestBody)
  }
}];

// Extract summary and 3 alt titles from Claude's structured response
const apiResponse  = $input.item.json;
const videoData    = $('Prepare Claude Request').item.json;

let summary   = '';
let altTitles = ['', '', ''];

try {
  const text = (apiResponse.content && apiResponse.content[0] && apiResponse.content[0].text) || '';

  const summaryMatch = text.match(/SUMMARY:\s*([\s\S]*?)(?=ALT TITLES:|$)/i);
  if (summaryMatch) summary = summaryMatch[1].trim();

  const titlesMatch = text.match(/ALT TITLES:\s*([\s\S]*?)$/i);
  if (titlesMatch) {
    const lines = titlesMatch[1]
      .split('\n')
      .map(l => l.replace(/^\d+\.\s*/, '').replace(/^[-*•]\s*/, '').trim())
      .filter(l => l.length > 0);
    altTitles = [lines[0] || '', lines[1] || '', lines[2] || ''];
  }
} catch (e) {
  summary = 'Error parsing AI response';
}

return [{
  json: {
    timestamp:         new Date().toISOString(),
    videoTitle:        videoData.videoTitle,
    videoUrl:          videoData.videoUrl,
    thumbnailUrl:      videoData.thumbnailUrl,
    channelName:       videoData.channelTitle,
    channelId:         videoData.channelId,
    publishedAt:       videoData.publishedAt,
    viewCount:         videoData.viewCount,
    likeCount:         videoData.likeCount,
    commentCount:      videoData.commentCount,
    channelAvgViews:   videoData.channelAvgViews,
    outlierScore:      videoData.outlierScore,
    baseScore:         videoData.baseScore,
    recencyBoost:      videoData.recencyBoost,
    contentBoost:      videoData.contentBoost,
    daysSincePublished: videoData.daysSincePublished,
    transcriptAvailable: videoData.transcriptAvailable,
    summary,
    altTitle1: altTitles[0],
    altTitle2: altTitles[1],
    altTitle3: altTitles[2],
    GOOGLE_SHEET_ID:   videoData.GOOGLE_SHEET_ID
  }
}];
